// 抖音的版本号转换
func (s *GetUIConfigInfoService) dyVersionCodeToInt(versionCode string) int {
	clientVersion := int(0)
	// 以.为分隔符，获取字符数组
	versionInfo := strings.Split(versionCode, ".")
	// 长度为1，说明为xxxxxx格式，直接返回
	if len(versionInfo) == 1 {
		clientVersion, _ := strconv.ParseInt(versionCode, 10, 0)
		return int(clientVersion)
	}
	// 获取高位版本号
	majorVersion, err := strconv.ParseInt(versionInfo[0], 10, 0)
	if err != nil {
		return 0
	}
	factor := 10
	if majorVersion > 9 {
		factor = 100
	}
	for _, value := range versionInfo {
		valueInt, err := strconv.ParseInt(value, 10, 0)
		if err != nil || valueInt > 99 {
			return 0
		}
		clientVersion = clientVersion*factor + int(valueInt)
		// "9.9.7"-->90+9-->990+7-->997
		// "10.0.1"-->1000+0-->100000+1-->100001
	}
	return clientVersion
}

